#!/usr/bin/env python3
"""Nine-site executive table (session arena/55dc7b72, 31 Oct 2026), generated from measurements.

Inputs:
  * scores: USER-REPORTED values copied from the request (NOT verified; no organizer receipt);
  * evidence/nine_site_audit_20261031.json (scripts/audit_nine_sites_20261031.py);
  * evidence/candidate_validation_catexcl_20261031.json (not used for the table rows).

Outputs:
  * evidence/nine_site_table_20261031.json
  * docs/executive-summary-20261031.html  (standalone page, regenerated by this script)

Duplicate rule (registry_roles.json, discrete_submission): duplicate if forward 3-px overlap
> 0.70 OR footprint Spearman > 0.90. Byte identity and identical dot sets are reported too.
"""
from __future__ import annotations

import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
AUDIT = ROOT / "evidence" / "nine_site_audit_20261031.json"
OUT_JSON = ROOT / "evidence" / "nine_site_table_20261031.json"
OUT_HTML = ROOT / "docs" / "executive-summary-20261031.html"

# site -> (best listed file name as in the prompt, USER-REPORTED score, all listed (name, score)),
# and the pinned local file that carries the same dot set.
SITES = {
    "GEMSDOE24": ("h25-1-dotted-h19-5-d1-5-20261002-989f59505db1-nan.tif", 0.2477,
                  "registry/GEMSDOE24_gems24-h25-1-dotted-h19-5-d1-5-20261002-989f59505db1-nan.tif"),
    "GEMSDOE25": ("dotted-h19-5-d2-8-20261002-e56ea318af89-nan.tif", 0.2600,
                  "registry/GEMSDOE25_d28.tif"),
    "GEMSDOE27": ("topo-gap-closure-t-v2-on-d1-5-20261002-5512495c6bd1-nan.tif", 0.2449,
                  "registry/GEMSDOE27_gems27-topo-gap-closure-t-v2-on-d1-5-20261002-5512495c6bd1-nan.tif"),
    "GEMSDOE28": ("h36-1-rung30-blind-r1-20261003-b531dae0a36f-nan.tif", 0.2710,
                  "registry/GEMSDOE28_gems28-h36-1-rung30-blind-r1-20261003-b531dae0a36f-nan.tif"),
    "GEMSDOE30": ("d28-poisson300m-offcat-44090-20261003T233156Z-91eae1ca.tif", 0.2600,
                  "registry/GEMSDOE30_gemsdoe30-d28-poisson300m-offcat-44090-20261003T233156Z-91eae1ca.tif"),
    "GEMSDOE31": ("h27-4-solo-d28-20261004-8acb75e1-nan.tif", 0.2708,
                  "registry/GEMSDOE31_gemsdoe31-h27-4-solo-d28-20261004-8acb75e1-nan.tif"),
    "GEMSDOE32": ("h33-h33-2-b2-20261004T220000Z-e5eb6e7e-zeros.tif", 0.2778,
                  "registry/GEMSDOE32_B2.tif"),
    "GEMSDOE33": ("h33d-analog-tip-stepover-r30-20261004-cb490425926e.tif", 0.2632,
                  "registry/GEMSDOE33_GEMSDOE33-h33d-analog-tip-stepover-r30-20261004-cb490425926e.tif"),
    "GEMSDOE36": ("anderson-geothermal-pinn-38854-20261004T230000Z-9b9ea4e6-zeros.tif", 0.2750,
                  "registry/GEMSDOE36_gemsdoe36-anderson-geothermal-pinn-38854-20261004T230000Z-9b9ea4e6-zeros.tif"),
}
LATTICE = "data/scored/13gems_20261001_r13-lattice-s5_v2_nan-outside.tif"


def main() -> int:
    audit = json.loads(AUDIT.read_text())
    entries = {e["key"]: e for e in audit["entries"]}
    pairs = {}
    for p in audit["pairs"]:
        pairs[(p["a"], p["b"])] = p
        pairs[(p["b"], p["a"])] = {**p, "a": p["b"], "b": p["a"],
                                   "forward_3px_a_to_b": p["reverse_3px_b_to_a"],
                                   "reverse_3px_b_to_a": p["forward_3px_a_to_b"]}

    def key_of(path: str) -> str:
        return ("focus/" if path.startswith("registry/") else "scored/") + Path(path).name

    rows = []
    for site, (best_name, score, local) in SITES.items():
        k = key_of(local)
        e = entries[k]
        focus_others = [key_of(v[2]) for s, v in SITES.items() if s != site]
        dup_focus, dup_identical = [], []
        for ko in focus_others:
            pr = pairs.get((k, ko))
            if pr is None:
                continue
            if pr["forward_3px_a_to_b"] > 0.70 or pr["spearman_footprint"] > 0.90:
                dup_focus.append(f"{ko.split('/')[1][:22]} (fwd {pr['forward_3px_a_to_b']:.3f}, rho {pr['spearman_footprint']:.3f})")
            if pr["subset_a_in_b"] and pr["subset_b_in_a"]:
                dup_identical.append(ko.split("/")[1][:22])
        lat = pairs.get((k, "scored/13gems_20261001_r13-lattice-s5_v2_nan-outside.tif"))
        rows.append({
            "site": site, "best_listed_file": best_name, "user_reported_score": score,
            "label": "USER-REPORTED / UNVERIFIED (no organizer receipt)",
            "local_file": local, "sha256": e["sha256"], "dots": e["dots_gt0_in_footprint"],
            "dots_on_catalogue": e["dots_on_catalogue"], "dots_within_2px_catalogue": e["dots_within_2px_catalogue"],
            "dots_within_3px_catalogue": e["dots_within_3px_catalogue"],
            "identical_dot_set_with_other_site": dup_identical,
            "literal_duplicate_of_other_focus_sites": dup_focus,
            "forward_3px_to_13GEMS_lattice": lat["forward_3px_a_to_b"] if lat else None,
            "literal_lattice_gate_trips": bool(lat and lat["forward_3px_a_to_b"] > 0.70),
            "leaderboard_estimate": "NOT ESTIMABLE (no organizer receipt; holdout measures a different target)",
            "ok_to_download_and_submit": False,
        })

    doc = {
        "schema": "karage1-nine-site-table-v1", "date_utc": "2026-10-31",
        "label": "Scores USER-REPORTED. Dot/overlap numbers are LOCAL MEASUREMENTS on pinned mirror bytes.",
        "rows": rows,
        "source_audit": str(AUDIT.relative_to(ROOT)),
    }
    OUT_JSON.write_text(json.dumps(doc, indent=2) + "\n")

    def td(x):
        return f"<td>{html.escape(str(x))}</td>"

    trs = []
    for r in rows:
        dup_txt = "; ".join(r["literal_duplicate_of_other_focus_sites"]) or "none above the literal gate"
        ident = ", ".join(r["identical_dot_set_with_other_site"]) or "none"
        trs.append("<tr>" + td(r["site"]) + td(r["best_listed_file"]) +
                   td(f"{r['user_reported_score']:.4f}") + td(f"{r['dots']:,}") +
                   td(f"{r['dots_within_2px_catalogue']:,}") + td(ident) + td(dup_txt) +
                   td("NO - " + ("lattice gate trips" if r["literal_lattice_gate_trips"] else "see duplicates")) +
                   td("NOT ESTIMABLE") + "</tr>")
    page = f"""<!doctype html><html lang="en"><head><meta charset="utf-8">
<title>GEMS nine-site executive summary (31 Oct 2026)</title>
<meta name="viewport" content="width=device-width,initial-scale=1">
<style>body{{font-family:system-ui,sans-serif;max-width:1200px;margin:24px auto;padding:0 16px;line-height:1.45}}
table{{border-collapse:collapse;width:100%;font-size:14px}}th,td{{border:1px solid #bbb;padding:6px;vertical-align:top}}
th{{background:#f2f2f2;text-align:left}}.banner{{background:#fff3cd;border:2px solid #b58900;padding:12px;border-radius:6px}}
.no{{color:#9b1c1c;font-weight:700}}</style></head><body>
<div class="banner"><strong>VERDICT: NOTHING IS CLEARED FOR DOWNLOAD OR SUBMISSION.</strong>
<p>No file on this page is OK to submit. The highest listed score (GEMSDOE32 B2, 0.2778) is a
<em>previous submission</em>; resubmitting it would be a copy. Scores are USER-REPORTED and unverified.
Estimated leaderboard score: <strong>not estimable</strong> for every file (no organizer receipt for any file).</p>
<p>New candidate: <code>docs/downloads/DO-NOT-SUBMIT_karage1-catexcl-halo-r3-t0.292-20261031T010556Z-zeros.tif</code>.
Unique versus the nine focus files, but it fails the literal 13GEMSDOE lattice gate (99.6%) and its holdout DTI is
below a density-matched random control. <span class="no">DO NOT SUBMIT.</span></p></div>
<h2>Nine-site table</h2>
<table><thead><tr><th>Site</th><th>Highest listed file</th><th>Score (USER-REPORTED)</th><th>Dots (local)</th>
<th>Dots within 2 px of USGS/INGENIOUS catalogue</th><th>Identical dot set with</th><th>Literal duplicate of (other focus sites)</th>
<th>OK to download &amp; submit?</th><th>Leaderboard estimate</th></tr></thead><tbody>{''.join(trs)}</tbody></table>
<h2>Sources (verify manually)</h2><ul>
<li><a href="https://www.drivendata.org/competitions/306/competition-doe-gems/page/967/">Problem description, metric and submission format (DrivenData)</a></li>
<li><a href="https://community.drivendata.org/t/scoring-clarification-are-known-usgs-ingenious-faults-masked-when-scoring-and-are-they-in-the-final-round-label-set/11516">Organizer answer: known USGS/INGENIOUS pixels are masked (topic 11516, 16 Sep 2026)</a></li>
<li><a href="https://www.drivendata.org/competitions/306/competition-doe-gems/leaderboard/">Public leaderboard</a></li>
<li><a href="https://docs.nlr.gov/docs/fy26osti/96647.pdf">DOE/NLR official rules (PDF)</a></li>
<li><a href="https://github.com/drivendataorg/gems-prize-reference-solution">Official reference solution (commit aebe92f)</a></li></ul>
<p><a href="../evidence/nine_site_table_20261031.json">Table data (JSON)</a> · <a href="../evidence/nine_site_audit_20261031.json">Full pairwise audit</a> ·
<a href="../knowledge/review-arena-55dc7b72-20261031.md">Session review</a></p></body></html>
"""
    OUT_HTML.write_text(page)
    for r in rows:
        print(r["site"], r["user_reported_score"], r["dots"], "dup_focus=", len(r["literal_duplicate_of_other_focus_sites"]),
              "ident=", r["identical_dot_set_with_other_site"], "lattice_fwd=", round(r["forward_3px_to_13GEMS_lattice"] or -1, 4))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
